// Simple function that returns a vector that contains all the file contents.
auto fileToVector (const string &filePath) -> vector<int>
{
    std::ifstream myfile {filePath};
    vector<int> v1;
    string line;
    if (myfile.is_open ())
    {
        while (getline (myfile, line))
        {
            v1.push_back (atoi (line.c_str ()));
        }
    }
    myfile.close ();
    return v1;
}

// Sorts the input array and returns the number of the inversions.
auto mergeSort (vector<int> &vec) -> unsigned long
{
    vector<int> temp (vec.size ());
    return _mergeSort (vec, temp, 0, vec.size () - 1);
}

// Recursive Sorts the input array and returns the number of the inversions.
auto _mergeSort (vector<int> &vec, vector<int> &temp, size_t left,
                 size_t right) -> unsigned long
{
    unsigned long invCount {};
    if (right > left)
    {
        // Divide the array into two parts
        size_t mid {(left + right) / 2};

        // Inversion count is the sum of left part, right part
        // and number in merging;
        invCount = _mergeSort (vec, temp, left, mid);
        invCount += _mergeSort (vec, temp, mid + 1, right);
        invCount += _mergeAndCount (vec, temp, left, mid + 1, right);
    }
    return invCount;
}

auto _mergeAndCount (vector<int> &vec, vector<int> &temp, size_t left,
                     size_t mid, size_t right) -> unsigned long
{
    unsigned long invCount {};
    size_t i {left}; //i is an index for left subarray
    size_t j {mid};  //j is an index for right subarray
    size_t k {left}; //k is an index for resultant merged subarray;

    // Traverse the two subarrays
    while ((i <= mid - 1) && (j <= right))
    {
        if (vec.at (i) <= vec.at (j))
        {
            // Copy first array's value (smallest) to the temp array and
            // increase the indexes. No inversion.
            temp.at (k++) = vec.at (i++);
        }
        else
        {
            // Copy second array's value. Add the inversions.
            temp.at (k++) = vec.at (j++);
            invCount += mid - i;
        }
    }

    // copy any left overs of the left subarray
    while (i <= mid - 1)
    {
        temp.at (k++) = vec.at (i++);
    }

    // copy any left overs of the right subarray
    while (j <= right)
    {
        temp.at (k++) = vec.at (j++);
    }

    // copy the merged elements back to the original array
    for (size_t n = left; n <= right; ++n)
    {
        vec.at (n) = temp.at (n);
    }
    return invCount;
}

